INSERT OR IGNORE INTO form_guides (form_code, guide_json, provider, model, generated_at)
SELECT column1, column2, column3, column4, column5 FROM (VALUES
  ('J1102-01', '{"purpose":"관리계획서의 표지. 어떤 품번·차종에 대한 계획이고 누가(상호기능팀) 만들고 언제 개정했는지를 보여 줍니다.","mustInclude":["도면과 동일한 품번·품명","상호기능팀원(2개 부서 이상)","제정일·개정일·개정사유","작성·검토·승인 서명"],"auditPoints":["공정흐름도·FMEA·작업표준서와 품번·Rev가 같은가","4M 변경 뒤 개정이 따라왔는가","승인자가 권한 있는 사람인가"],"commonFindings":["현장 게시본과 정본 Rev 불일치","개정사유가 공란","팀원이 품질팀 한 명뿐"],"tips":["개정사유에 4M 변경 의뢰서 번호를 같이 적으면 추적성 질문이 끝납니다","표지 Rev를 바꿀 때 공정흐름도·FMEA도 같은 날 개정"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('J1103-01', '{"purpose":"작업자가 공정에서 무엇을 어떤 조건으로 어떤 순서로 하는지 정한 문서. 현장에 게시되어 교육·감사의 기준이 됩니다.","mustInclude":["작업 순서(번호)","작업 조건 수치(전류·온도·시간·압력 등)","자주검사 시점과 항목","이상 발생 시 조치(정지→격리→호출)","안전 주의사항"],"auditPoints":["현장 작업자가 실제로 이 순서·조건대로 하는가(직접 질문)","관리계획서의 관리 항목과 조건이 일치하는가","게시본 Rev가 정본과 같은가"],"commonFindings":["조건이 ''적정'' 같은 말로만 적혀 수치 없음","검사 시점이 없음","작업자가 표준서 위치를 모름"],"tips":["사진이나 그림보다 수치가 먼저입니다","이상 조치 3단계(정지·격리·호출)는 한 줄로 박아 두세요","신규 작업자 교육 기록과 연결하면 6_5 자격 항목도 같이 해결"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('J1101-01', '{"purpose":"공정별로 무엇이 잘못될 수 있고(고장형태) 그 영향·원인·현재 관리를 평가해 위험이 큰 곳에 조치를 정하는 문서.","mustInclude":["공정 기능과 요구사항","고장형태·영향·원인 분리 기술","예방/검출 관리 현황","S·O·D 평가와 권고 조치·책임·기한","조치 후 재평가"],"auditPoints":["위험 큰 항목에 조치가 실제로 실행·완료됐는가","관리계획서 관리 항목이 FMEA 검출 관리와 같은가","고객 불만·내부 부적합이 FMEA에 반영됐는가"],"commonFindings":["고장형태와 원인이 섞여 있음","권고조치 공란","불량 발생 후 FMEA 미갱신"],"tips":["불량이 나면 대책서와 같이 FMEA 한 줄을 고치는 습관","상호기능팀 서명은 실제 회의 기록과 날짜를 맞추세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('J1100-02', '{"purpose":"원자재 입고부터 출하까지 공정 순서를 그림으로 보여 주고 특별특성(KPC)이 어느 공정에 있는지 표시합니다.","mustInclude":["공정 번호(OP)와 명칭","검사·이동·보관 기호","특별특성 표시","품번·Rev"],"auditPoints":["관리계획서·FMEA·작업표준서의 공정 번호와 일치","현장 실제 레이아웃과 같은가","외주 공정 표시"],"commonFindings":["외주 공정 누락","공정 번호 불일치","Rev 미관리"],"tips":["공정 번호는 10 단위로 매겨 끼워 넣기 쉽게","KPC는 관리계획서 ◇ 표기와 1:1로"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L1100-07', '{"purpose":"작업 전 설비 상태(급유·압력·안전장치 등)를 매일 확인한 기록. 설비 고장으로 인한 불량을 막는 첫 관문입니다.","mustInclude":["점검 항목별 기준(수치·범위)","일자별 점검 결과와 점검자","이상 시 조치 내용","확인자 서명"],"auditPoints":["점검 항목에 기준값이 있는가","이상 표시가 실제 조치로 이어졌는가","주말·휴일 공란이 자연스러운가(가짜 기록 의심)"],"commonFindings":["전부 ○만 찍힌 형식 기록","기준값 없이 ''정상''","점검자 공란"],"tips":["기준값이 없는 항목은 지금 바로 추가하세요","이상 발견 건수가 0인 달이 몇 달째면 심사원이 더 의심합니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M1100-02', '{"purpose":"설비가 멈춘 시간과 원인을 기록해 비가동 손실을 관리합니다.","mustInclude":["일자·설비·비가동 시간","원인 코드","조치 내용","담당자"],"auditPoints":["반복 원인에 대한 개선 활동이 있는가","월 집계가 경영검토·KPI에 연결되는가"],"commonFindings":["원인 코드 없이 ''기타''만","시간 합계 불일치"],"tips":["비가동 코드를 10개 이내로 정해 두면 집계가 쉬워집니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M1200-03', '{"purpose":"주간조와 야간조가 설비·품질·안전·자재 상황을 서로 넘기는 기록. 인수인계 누락으로 생기는 불량을 막습니다.","mustInclude":["조별 작성자·일자","설비·품질·안전·자재·기타 이슈","격리 LOT·미결 사항"],"auditPoints":["이슈가 다음 조에서 조치됐는가","부적합 통보서 번호와 연결되는가"],"commonFindings":["''특이사항 없음''만 반복","미결 사항이 다음 조 기록에 없음"],"tips":["시각 + 조치 + 결과 세 가지를 적으면 한 줄이어도 충분합니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M1200-10', '{"purpose":"작업자가 공정에서 초품·중품·종품을 스스로 검사한 기록. 공정 품질의 가장 기본 증거입니다.","mustInclude":["초·중·종 3회 시점","검사 항목별 기준과 실측값","판정과 검사자","이상 시 조치"],"auditPoints":["실측값이 숫자로 있는가(○/× 금지)","검사 항목이 관리계획서와 같은가","불합격 시 부적합 처리로 이어졌는가"],"commonFindings":["○만 찍힘","초품 검사 없이 본작업","측정기 관리번호 없음"],"tips":["측정기 번호를 적으면 계측기 관리 항목(2_5)까지 같이 증명됩니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L2100-05', '{"purpose":"품질 담당이 공정을 돌며 작업 조건·검사 상태를 점검한 기록. 작업자 자주검사를 독립적으로 확인합니다.","mustInclude":["순회 시각·공정·설비","점검 항목과 결과","소재 LOT","이상 시 조치"],"auditPoints":["순회 주기가 규정대로 지켜졌는가","이상 발견이 기록·조치로 남는가"],"commonFindings":["순회 주기 누락","전 항목 적합만 반복"],"tips":["자주검사 기록과 같은 LOT·시각을 적어 두면 대조가 쉽습니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L2100-01', '{"purpose":"원자재·구매품을 받았을 때 무엇을 어떻게 검사할지 정한 기준. 수입검사 기록의 근거입니다.","mustInclude":["품번별 검사 항목·기준·방법","시료 수와 합부 기준","측정기","성적서 요구 여부"],"auditPoints":["검사 기록이 이 기준대로 됐는가","기준 개정 이력"],"commonFindings":["기준은 있는데 기록이 기준과 다름","시료 수 미명시"],"tips":["공급사 성적서를 받는 항목은 ''성적서 확인''으로 검사 방법을 적어 두세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('K1200-07', '{"purpose":"외주 업체의 초도품 검사(ISIR)와 검사협정서 접수·개정 이력을 관리합니다.","mustInclude":["업체·품번·접수일","ISIR/협정서 Rev","승인 여부·담당"],"auditPoints":["4M 변경 시 ISIR 재접수가 있는가","협정서 유효기간"],"commonFindings":["변경 후 ISIR 미접수","협정서 만료"],"tips":["4M 변경 대장과 번호로 연결해 두세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L2100-07', '{"purpose":"수입검사 결과를 입고별로 누적한 대장. 공급사 품질 추세와 합부 이력의 근거입니다.","mustInclude":["입고일·품번·LOT·수량","검사 결과(실측)·판정","검사자","불합격 시 처리"],"auditPoints":["불합격 건이 공급사 통보·시정조치로 이어졌는가","성적서 첨부 확인"],"commonFindings":["합격만 있고 실측값 없음","불합격 처리 기록 없음"],"tips":["공급사별 PPM을 월말에 뽑아 협력사 모니터링에 쓰세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L2300-01', '{"purpose":"외관 합부 판정에 쓰는 한도견본의 등록·유효기간·연장·폐기를 관리합니다.","mustInclude":["관리번호·품번·품질특성","등록일·유효기간","연장 승인","폐기 기록"],"auditPoints":["현장 견본에 유효기간 표시가 있는가","유효기간 경과 견본 사용 여부"],"commonFindings":["유효기간 경과","현장 견본과 대장 불일치"],"tips":["견본 사진을 대장에 같이 붙이면 교체 시 혼동이 없습니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L2200-01', '{"purpose":"제품 신뢰성 시험(내구·환경 등)의 연간 계획과 실적을 관리합니다.","mustInclude":["시험 항목·주기","월별 계획/실적","시험 기관·성적서 번호"],"auditPoints":["고객 요구 주기를 지켰는가","실적 성적서가 실제로 있는가"],"commonFindings":["계획만 있고 실적 없음","시험 주기 근거 불명"],"tips":["고객 사양서에서 요구 주기를 찾아 계획서 비고에 적어 두세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L3100-01', '{"purpose":"측정기(계측기) 전체를 관리번호로 등록하고 교정 주기·다음 교정일을 관리합니다.","mustInclude":["관리번호·명칭·규격","교정 주기·최근/다음 교정일","보관 위치·담당"],"auditPoints":["현장 측정기에 관리번호·교정 라벨이 붙어 있는가","교정 유효기간 경과 측정기"],"commonFindings":["라벨 없음","대장에 없는 측정기 사용"],"tips":["교정 만료 한 달 전 알림을 정기 의무에 걸어 두세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L3100-03', '{"purpose":"계측기별 교정 시기를 연간으로 계획하고 실시 여부를 표시합니다.","mustInclude":["관리번호별 교정 월","계획(○)/실시(●) 표시","외부/내부 교정 구분"],"auditPoints":["계획 대비 실시율","교정 성적서 보관"],"commonFindings":["계획만 있고 ● 없음"],"tips":["교정 성적서 번호를 실시 칸 옆에 적으면 찾기 쉽습니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L3100-04', '{"purpose":"측정기를 사용하기 전 외관·0점을 확인하고 이상 시 조치를 기록합니다.","mustInclude":["기기번호","점검 결과","이상 내용·조치·완료일","확인자"],"auditPoints":["이상 측정기로 측정한 제품을 재검했는가"],"commonFindings":["이상 조치 기록 없음"],"tips":["예비 측정기 번호를 조치란에 적어 두면 추적이 됩니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L3101-02', '{"purpose":"측정 시스템(사람+측정기)의 반복성·재현성을 평가해 측정값을 믿을 수 있는지 확인합니다.","mustInclude":["측정자 3명·시료 10개·반복 2~3회","%GRR 결과와 판정 기준","평가 대상 측정기 번호"],"auditPoints":["관리계획서의 KPC 측정기에 대해 실시했는가","%GRR 10% 초과 시 조치"],"commonFindings":["시료 수 부족","판정 기준 미기재"],"tips":["10% 미만 적합·10~30% 조건부·30% 초과 부적합을 양식에 같이 적으세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M3100-05', '{"purpose":"출하 전 완성품을 샘플 검사한 결과와 판정. 고객에게 불량이 나가지 않았다는 마지막 증거입니다.","mustInclude":["품번·LOT·생산일·검사일","검사 항목별 기준·실측","시료 수·판정","검사자·확인자"],"auditPoints":["포장 라벨 LOT와 성적서 LOT 일치","샘플 수가 기준서와 같은가"],"commonFindings":["실측값 없이 합격","LOT 불일치"],"tips":["출하관리대장과 같은 LOT 번호 체계를 쓰세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M3100-01', '{"purpose":"출하 이력(일자·품번·LOT·수량·거래처)을 누적해 역추적의 출발점이 됩니다.","mustInclude":["출하일·거래처","품번·LOT·수량","출하검사 성적서 번호"],"auditPoints":["고객 불만 LOT를 출하 기록에서 찾을 수 있는가"],"commonFindings":["LOT 누락"],"tips":["성적서 번호를 같이 적으면 역추적 시간이 반으로 줍니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('B1100-12', '{"purpose":"기밀(리크) 불량의 발생~리워크~재검사~판정을 추적합니다.","mustInclude":["발생 LOT·수량","리워크 방법·작업자","재검사 실측·판정","리워크 LOT 식별(-R)"],"auditPoints":["리워크 후 재검사 기록","리워크 LOT 식별이 현장에서 보이는가"],"commonFindings":["재검사 없이 출하","식별 없음"],"tips":["리워크 기준표(허용/금지)를 대장 첫 장에 붙여 두세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L1100-12', '{"purpose":"설비 정기점검의 월간 계획과 실시를 관리합니다.","mustInclude":["설비별 점검 항목·주기","계획/실시 표시","점검자"],"auditPoints":["계획 대비 실시율","미실시 사유"],"commonFindings":["실시 표시 누락"],"tips":["연간 예방보전 계획서와 같은 설비 번호를 쓰세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L1200-12', '{"purpose":"지그·치공구의 일상 점검 결과를 월 단위로 기록합니다.","mustInclude":["지그 번호","일자별 점검 결과·점검자","이상 시 조치"],"auditPoints":["이상 지그 사용 중지 여부","검사 성적서와 연결"],"commonFindings":["○만 반복"],"tips":["마모 기준(수치)을 체크시트 상단에 적어 두세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L1100-25', '{"purpose":"금형의 일상·정기·보관 점검 결과를 기록해 금형 상태와 타발수를 관리합니다.","mustInclude":["금형 번호·등급","점검 항목별 결과","타발수·수리 이력","점검자"],"auditPoints":["타발수 기준 도달 시 점검·수리가 있었는가","보관 금형 방청 상태"],"commonFindings":["타발수 미기록","보관 점검 없음"],"tips":["금형마스터의 타발 누계와 같은 값을 쓰세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M2100-10', '{"purpose":"원자재 LOT → 공정 → 완제품 LOT를 연결해 역추적을 가능하게 합니다.","mustInclude":["완제품 LOT","투입 원자재·부자재 LOT","공정·일자·작업자","수입검사 성적서 번호"],"auditPoints":["임의 LOT로 역추적 시연(목표 10분 이내)","기록 간 LOT 표기 일치"],"commonFindings":["부자재 LOT 누락","역추적에 30분 이상"],"tips":["월 1회 모의 역추적을 해 보고 소요 시간을 적어 두면 5_1 만점 근거가 됩니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('K2100-06', '{"purpose":"자재·제품을 먼저 들어온 것부터 쓰도록(FIFO) 방법을 정한 기준서.","mustInclude":["보관 위치 규칙","라벨·색 표시 방법","역전 발견 시 조치","담당"],"auditPoints":["현장에서 실제로 앞 LOT가 먼저 나가는가"],"commonFindings":["기준은 있는데 현장 표시 없음"],"tips":["월별 색상 라벨이 가장 싸고 확실합니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('D1100-05', '{"purpose":"공정의 안전 상태(가스·전기·시설)를 정기 점검한 기록.","mustInclude":["점검일·점검자","항목별 결과","특이사항·조치"],"auditPoints":["지적 사항이 개선대책으로 이어졌는가"],"commonFindings":["조치 기록 없음"],"tips":["사진 1장이 글 열 줄보다 낫습니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('J3100-01', '{"purpose":"사람·설비·재료·방법이 바뀔 때 영향을 평가하고 검증·고객 통보를 결정하는 의뢰서.","mustInclude":["변경 전/후","변경 사유","품질 영향과 검증 계획","고객 통보 필요 여부","승인"],"auditPoints":["변경 후 초도품 검증 기록","관리계획서·FMEA 개정 연결","고객 승인 필요 건의 승인서"],"commonFindings":["변경 후 문서 미개정","고객 통보 누락"],"tips":["판단기준표를 옆에 두고 통보 필요 여부를 체크하세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('J3100-03', '{"purpose":"4M 변경 의뢰의 접수~검증~적용~고객 승인을 한 표로 관리합니다.","mustInclude":["의뢰 번호·일자","변경 내용 요약","검증 완료일","고객 승인 여부"],"auditPoints":["모든 변경이 여기 있는가(설비 교체·작업자 교체 포함)"],"commonFindings":["작업자 교체 미등록"],"tips":["설비 이력카드의 교체 기록과 대조해 누락을 찾으세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('A5100-01', '{"purpose":"3개년 내부심사 계획과 실적. 모든 공정·프로세스가 연 1회 이상 심사됐음을 보여 줍니다.","mustInclude":["연도·분기별 계획(○)·실시(●)","공정심사·시스템심사 구분","작성일·승인"],"auditPoints":["전 공정이 연간 1회 이상 포함","실시 ● 뒤에 보고서가 있는가"],"commonFindings":["일부 공정 누락","계획만 있고 실적 없음"],"tips":["고객 불만이 난 공정은 계획에 없어도 추가 심사 ●를 찍으세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('A5100-03', '{"purpose":"내부심사 결과 보고서. 긍정적 측면·부적합·공정/제품 심사 결과를 정리합니다.","mustInclude":["심사 일자·대상·심사원","부적합 내역(어디서·무엇이·기준)","시정조치 요구서 번호","종합 의견"],"auditPoints":["부적합이 시정조치·유효성 확인까지 갔는가","심사원 독립성"],"commonFindings":["부적합 0건만 반복(실효성 의심)","시정조치 미연결"],"tips":["부적합이 0이면 관찰사항이라도 2~3개 적으세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('A5200-03', '{"purpose":"제조 공정 내부심사 체크리스트. 공정별 문항을 평가하고 지적사항을 적습니다.","mustInclude":["평가 대상 공정·일자·평가자","문항별 결과","지적사항·점수"],"auditPoints":["문항이 관리계획서 항목을 다루는가"],"commonFindings":["전 문항 적합"],"tips":["지적 4건 칸이 비면 심사원이 더 의심합니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('A5200-04', '{"purpose":"생산된 제품을 뽑아 기준과 대조한 제품 심사 기록.","mustInclude":["거래처·품번·생산일·LOT","검사 항목별 실측·판정","평가자"],"auditPoints":["실측값 존재","불합격 시 조치"],"commonFindings":["실측 없이 합격"],"tips":["출하검사 성적서와 다른 샘플을 쓰세요(독립성)"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('F2100-01', '{"purpose":"사내 자격(공정 작업자·검사원·내부심사원 등) 보유자와 유효기간을 관리합니다.","mustInclude":["자격 구분·번호","성명·부서","부여일·유효일·갱신주기"],"auditPoints":["특수공정·검사 작업자가 전원 자격 보유","유효기간 경과자 작업 여부"],"commonFindings":["유효기간 만료 후 작업","신규 작업자 미등록"],"tips":["작업자 배치표와 월 1회 대조하세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('F2100-11', '{"purpose":"자격 인증 교육을 실시하고 이론·실기 평가한 기록.","mustInclude":["인적 정보","교육명·기간·강사","이론·실기 점수와 합격 기준","교육 자료"],"auditPoints":["합격 기준 명시","불합격자 재교육"],"commonFindings":["점수만 있고 기준 없음"],"tips":["합격 기준(예: 80점)을 양식 상단에 고정 인쇄하세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('F1100-01', '{"purpose":"연간 교육훈련 계획과 월별 실적.","mustInclude":["과정명·대상·월 계획","실적 표시","승인"],"auditPoints":["계획 대비 실시율","법정 교육 포함"],"commonFindings":["실적 미표시"],"tips":["교육 보고서 번호를 실적 칸에 적으세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('B1100-01', '{"purpose":"부적합품이 발견됐을 때 발생 사실·내용·조치를 통보하는 첫 기록. 시정조치의 출발점입니다.","mustInclude":["발생일·장소·품번·LOT·수량","부적합 내용(실측)","원인 조사","조치·요구사항","관리대장 번호"],"auditPoints":["격리 → 처리 결정 → 시정조치 흐름","대장 번호 연결"],"commonFindings":["수량·LOT 누락","조치 없이 종결"],"tips":["사진을 붙이고 실측값을 숫자로 적으면 원인 분석이 빨라집니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('B1100-13', '{"purpose":"부적합품의 격리~재검사~폐기/리워크/복귀 수량을 맞추는 처리대장.","mustInclude":["격리 수량","처리 구분별 수량","처리일·담당","수량 대사"],"auditPoints":["들어온 수량 = 나간 수량 합","폐기 승인"],"commonFindings":["수량 불일치"],"tips":["대사가 안 맞으면 그 자리에서 원인을 적어 두세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('B1100-03', '{"purpose":"규격을 벗어난 제품을 그대로/수정해서 쓰려 할 때 고객 승인 여부를 판단하고 기록하는 의뢰서.","mustInclude":["부적합 내용(실측·수량·LOT)","특채 종류","고객 승인 필요 여부와 승인서","식별 방법"],"auditPoints":["고객 승인 없이 특채 출하 여부","특채품 식별·추적"],"commonFindings":["승인서 없음","특채 LOT 미식별"],"tips":["치수 부적합은 거의 항상 고객 승인 대상으로 보세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('B2200-05', '{"purpose":"월별 품질 실적(PPM)을 목표와 비교해 경영검토에 올립니다.","mustInclude":["연간 목표 PPM(공정·고객·외주)","월별 실적","목표 대비 달성"],"auditPoints":["목표 미달 시 개선 활동","KPI 기준정보와 목표 일치"],"commonFindings":["목표 없음","미달 원인 분석 없음"],"tips":["PPM 계산식(불량수/검사수×100만)을 양식에 적어 두세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M4200-01', '{"purpose":"작업장 조도를 측정해 검사·작업에 필요한 밝기 기준을 만족하는지 확인합니다.","mustInclude":["측정 위치·기준 조도","측정값·판정","측정일·측정자"],"auditPoints":["검사대 조도 기준 충족","기준 미달 시 조치"],"commonFindings":["기준값 없음"],"tips":["검사대는 보통 더 높은 기준이 적용됩니다 — 위치별 기준을 구분하세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M4100-02', '{"purpose":"현장의 정리·정돈·청소·청결·습관화 상태를 점수로 진단합니다.","mustInclude":["점검일·구역·점검자","항목별 점수","지적사항"],"auditPoints":["지적이 시정대책으로 이어졌는가"],"commonFindings":["점수만 있고 지적 없음"],"tips":["전/후 사진이 가장 좋은 증거입니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M1200-09', '{"purpose":"공정 간 제품 이동 수량과 부자재 사용량을 맞춰 누락·과다 사용을 찾습니다.","mustInclude":["품번·LOT·수량","전 공정 완료 수량과 대사","부자재 사용량"],"auditPoints":["수량 차이 소명"],"commonFindings":["차이 원인 미기재"],"tips":["차이가 나면 ''불량 폐기 n + 낙하 n''처럼 원인을 숫자로"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('B2300-08', '{"purpose":"정성품질 항목 16개를 라인별로 순회 점검합니다.","mustInclude":["점검일·점검자·라인","항목별 결과","지적·조치"],"auditPoints":["지적 반복 여부"],"commonFindings":["조치 미기록"],"tips":["지적 반복 라인은 취합 대장에 올려 개선 과제로"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('B2300-03', '{"purpose":"고객 정성품질 유도 방안의 점검 현황을 기록합니다.","mustInclude":["점검일·점검자·대응자","점검 품목","특이사항"],"auditPoints":["점검 주기 준수"],"commonFindings":["특이사항 공란"],"tips":["특이사항이 없으면 확인한 항목 수라도 적으세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M1200-11', '{"purpose":"특수공정(열처리·용접·도장 등)의 조건을 하루 3회 기록해 조건 관리가 됐음을 증명합니다.","mustInclude":["구간별 온도·유량·속도 등 실측값","기준 범위","기록 시각·기록자","이상 시 조치"],"auditPoints":["실측값이 기준 범위 안인가","자동 기록계 차트와 대조","조건 이탈 시 제품 처리"],"commonFindings":["○/× 만 기록","이탈 시 조치 없음"],"tips":["자동 기록계 출력물을 같이 철하면 이 시트가 심사 만점 증거가 됩니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('M2100-01', '{"purpose":"LOT 번호 체계와 기록 시점·장소·담당을 정한 기준서.","mustInclude":["LOT 번호 규칙","기록 시점(입고·공정·출하)","담당 부서"],"auditPoints":["현장 LOT 표기가 기준대로인가"],"commonFindings":["규칙과 현장 표기 불일치"],"tips":["품번-YYMMDD-차수 같은 단순 규칙이 가장 오래갑니다"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L1100-09', '{"purpose":"설비 1대의 기본 정보와 수리·보전 이력을 누적하는 카드.","mustInclude":["설비 번호·명칭·도입일","수리·보전 일자·내용·비용","담당"],"auditPoints":["고장 조치 보고서와 이력 일치"],"commonFindings":["이력 미갱신"],"tips":["고장 보고서 번호를 이력란에 적어 두세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('L1100-11', '{"purpose":"설비별 예방보전(PM) 주기를 정하고 연간 계획/실시를 표시합니다.","mustInclude":["설비별 점검 주기","월별 계획(○)/실시(●)","담당"],"auditPoints":["중요 설비 전부 포함","실시율"],"commonFindings":["실시 누락"],"tips":["중요설비 체크리스트의 A등급 설비는 주기를 짧게"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
  ('B2100-01', '{"purpose":"부적합 사항에 대해 원인 분석과 시정·예방조치를 요구하고 완료·유효성까지 추적합니다.","mustInclude":["발행 번호·일자·대상","부적합 내용과 기준","원인 분석(5-Why)","시정조치·예방조치·기한","유효성 확인"],"auditPoints":["유효성 확인이 실제로 됐는가(재발 여부)","기한 준수"],"commonFindings":["원인이 ''작업자 부주의''뿐","유효성 확인 미기재"],"tips":["원인은 시스템 관점(표준·교육·설비)으로 한 번 더 물어보세요"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z'),
