  ('H3200-02', '{"purpose":"고객 불만 1건에 대한 대응 조치 결과를 고객에게 회신하는 보고서.","mustInclude":["접수 내용·LOT·수량","원인 분석","조치·재발 방지","유효성·회신일"],"auditPoints":["회신 기한 준수","재발 여부"],"commonFindings":["회신 지연","유효성 미확인"],"tips":["고객 양식이 있으면 고객 양식을 우선 쓰고 사본을 여기에"]}', 'standard-pack', 'bot-authored-v1', '2026-08-23T00:00:00.000Z')
